const request = $('Получить запрос').first().json.body;
const opening = $input.first().json.message?.content?.trim() ?? '';
const intro = /^(?:Просим|Направляем|Предлагаем)[^\d\r\n«»"]{10,140}\.$/u.test(opening)
  ? opening : 'Просим рассмотреть следующие предложения по проекту договора.';

const changes = request.findings.map((finding, index) => {
  const {title, template, carrier, explanation} = finding;
  const location = carrier?.location ?? template?.location;
  let proposal;
  if (title === 'Отсутствует приложение') {
    proposal = 'Просим приложить к договору: ' + explanation + '.';
  } else if (title === 'Добавлено' && carrier) {
    proposal = 'Просим исключить следующее условие из проекта: «' + carrier.quote + '».';
  } else if (template) {
    proposal = 'Просим предусмотреть редакцию шаблона: «' + template.quote + '».';
  } else {
    proposal = 'Просим подтвердить указанные в проекте сведения: «' + carrier.quote + '».';
  }
  return (index + 1) + '. ' + title + ' · ' + location + '\n' + proposal;
});
return [{json:{output:[
  'Тема: Замечания к проекту договора «' + request.contractName.replace(/[\r\n]/g, ' ') + '»',
  'Добрый день!', intro, ...changes, 'Просим направить обновлённую редакцию проекта.'
].join('\n\n')}}];
